participantForm.addEventListener("submit", (event) => {
  event.preventDefault();
  const name = participantNameInput.value.trim();
  const amount = Number(participantInitialInput.value);
  const color = participantColorInput.value;

  if (!name || !Number.isFinite(amount) || amount < 0) {
    return;
  }

  const participantId = createId();
  state.participants.push({
    id: participantId,
    name,
    color,
  });

  state.contributions.push({
    id: createId(),
    participantId,
    amount,
    type: "initial",
    note: "Startinleg",
    date: todayIso(),
  });

  participantForm.reset();
  participantColorInput.value = "#7A8446";
  persistAndRender();
});

topupForm.addEventListener("submit", (event) => {
  event.preventDefault();
  const amount = Number(topupAmountInput.value);
  const note = topupNoteInput.value.trim();

  if (!Number.isFinite(amount) || amount <= 0) {
    return;
  }

  state.contributions.unshift({
    id: createId(),
    participantId: "",
    amount,
    type: "topup",
    note,
    date: todayIso(),
  });

  topupForm.reset();
  persistAndRender();
});

expenseForm.addEventListener("submit", async (event) => {
  event.preventDefault();
  const payload = await collectExpenseForm();
  if (!payload) {
    return;
  }

  const targetCollection = payload.kind === "estimate" ? state.estimates : state.expenses;
  const { kind, ...record } = payload;
  targetCollection.unshift(record);
  if (kind === "estimate") {
    activeTab = "overzicht";
    filterCategory.value = "all";
  }
  resetExpenseComposer();
  persistAndRender();
});

