analyzeReceiptButton.addEventListener("click", async () => {
  const requestPayload = {
    fileName: expenseReceiptInput.files[0]?.name || "",
    notesHint: [expenseDescriptionInput.value, expenseNoteInput.value].filter(Boolean).join(" "),
  };

  try {
    const result = await requestReceiptAnalysis(requestPayload);

    if (result.amount) {
      expenseAmountInput.value = result.amount;
    }
    if (result.description) {
      expenseDescriptionInput.value = result.description;
    }
    if (result.date) {
      expenseDateInput.value = result.date;
    }
    if (result.category) {
      expenseCategoryInput.value = result.category;
    }

    showReceiptReview(result.message, result.ocrStatus);
  } catch (error) {
    showReceiptReview(error.message, "manual_required");
  }
});

participantsList.addEventListener("click", (event) => {
  const target = event.target.closest("[data-action]");
  if (!target) {
    return;
  }

  const participantId = target.dataset.id;

  if (target.dataset.action === "edit-participant") {
    editingParticipantId = participantId;
    renderParticipants();
    return;
  }

  if (target.dataset.action === "cancel-participant") {
    editingParticipantId = null;
    renderParticipants();
    return;
  }

  if (target.dataset.action === "save-participant") {
    const card = target.closest("[data-participant-card]");
    saveParticipantEdits(participantId, card);
    return;
  }

  if (target.dataset.action === "remove-participant") {
    state.participants = state.participants.filter((participant) => participant.id !== participantId);
    state.contributions = state.contributions.filter((item) => item.participantId !== participantId);
    if (editingParticipantId === participantId) {
      editingParticipantId = null;
    }
    persistAndRender();
  }
});

