function loadState() {
  const savedState = readFromStorage(storageKey);
  if (!savedState) {
    return normalizeState(cloneData(demoState));
  }

  try {
    return normalizeState(JSON.parse(savedState));
  } catch (error) {
    return normalizeState(cloneData(demoState));
  }
}

function normalizeState(rawState) {
  const nextState = rawState && typeof rawState === "object" ? rawState : {};
  const participants = Array.isArray(nextState.participants) ? nextState.participants : [];
  const contributions = Array.isArray(nextState.contributions) ? nextState.contributions : [];
  const expenses = Array.isArray(nextState.expenses) ? nextState.expenses : [];
  const estimates = Array.isArray(nextState.estimates) ? nextState.estimates : [];

  return {
    weekend: {
      name: nextState.weekend?.name || "Op z'n Loatst",
      appName: nextState.weekend?.appName || "Pot z,n Loatst",
    },
    auth: {
      loggedIn: Boolean(nextState.auth?.loggedIn),
      provider: sanitizeText(nextState.auth?.provider || "local", 40) || "local",
      email: sanitizeText(nextState.auth?.email || "", 120),
    },
    profile: {
      name: sanitizeText(nextState.profile?.name || "", 80),
      avatarUrl: sanitizeImageValue(nextState.profile?.avatarUrl || ""),
    },
    participants: participants.map((participant, index) => ({
      id: participant.id || createId(),
      name: sanitizeText(participant.name) || `Deelnemer ${index + 1}`,
      color: participant.color || fallbackColor(index),
    })),
    contributions: contributions
      .filter((item) => item && typeof item === "object")
      .map((item) => ({
        id: item.id || createId(),
        participantId: item.type === "topup" ? "" : item.participantId || "",
        amount: sanitizeAmount(item.amount),
        type: item.type === "topup" ? "topup" : "initial",
        note: sanitizeText(item.note),
        date: sanitizeDate(item.date),
      })),
    expenses: expenses
      .filter((item) => item && typeof item === "object")
      .map((item) => ({
        id: item.id || createId(),
        description: sanitizeText(item.description) || "Uitgave",
        amount: sanitizeAmount(item.amount),
        category: categoryLabels[item.category] ? item.category : "overig",
        paidBy: sanitizeText(item.paidBy),
        date: sanitizeDate(item.date),
        note: sanitizeText(item.note),
        receiptImage: sanitizeImageValue(item.receiptImage),
        ocrStatus: item.ocrStatus || "manual",
      })),
    estimates: estimates
      .filter((item) => item && typeof item === "object")
      .map((item) => normalizeEstimate(item, participants.length)),
  };
}

function createEmptyState() {
  return normalizeState({
    weekend: {
      name: "Op z'n Loatst",
      appName: "Pot z,n Loatst",
    },
    auth: {
      loggedIn: false,
      provider: "local",
      email: "",
    },
    profile: {
      name: "",
      avatarUrl: "",
    },
    participants: [],
    contributions: [],
    expenses: [],
    estimates: [],
  });
}

function persistAndRender() {
  writeToStorage(storageKey, JSON.stringify(state));
  render();
}

function render() {
  renderLoginGate();
  renderTabs();
  renderSummary();
  renderParticipants();
  renderTopups();
  renderExpenses();
  renderTimeline();
  renderWeekendLogo();
  renderAccountUi();
  positionMenuPanel();
}

function renderLoginGate() {
  const loginWall = document.querySelector("#login-wall");
  const tabBar = document.querySelector(".tab-bar");
  const loggedIn = !!state.auth?.loggedIn;
  if (loginWall) loginWall.hidden = loggedIn;
  if (tabBar) tabBar.hidden = !loggedIn;
  if (summaryCards) summaryCards.hidden = !loggedIn;
  if (!loggedIn) tabPanels.forEach(p => { p.hidden = true; });
}

function toggleAccountDropdown() {
  if (!accountDropdown) return;
  const next = accountDropdown.hidden;
  accountDropdown.hidden = !next;
  accountToggleButton?.setAttribute("aria-expanded", next ? "true" : "false");
}

function closeAccountDropdown() {
  if (!accountDropdown) return;
  accountDropdown.hidden = true;
  accountToggleButton?.setAttribute("aria-expanded", "false");
}

function positionMenuPanel() {
  if (!menuPanelContent || !menuPanelTrigger || !menuPanel?.classList.contains("is-open")) {
    if (menuPanelContent) {
      menuPanelContent.hidden = true;
    }
    menuBackdrop.hidden = true;
    return;
  }

  menuBackdrop.hidden = false;
  menuPanelContent.hidden = false;
}

function toggleMenuPanel() {
  if (!menuPanel) {
    return;
  }
  const nextOpen = !menuPanel.classList.contains("is-open");
  menuPanel.classList.toggle("is-open", nextOpen);
  if (menuPanelTrigger) {
    menuPanelTrigger.setAttribute("aria-expanded", nextOpen ? "true" : "false");
  }
  positionMenuPanel();
}

function closeMenuPanel() {
  if (!menuPanel) {
    return;
  }
  menuPanel.classList.remove("is-open");
  if (menuPanelTrigger) {
    menuPanelTrigger.setAttribute("aria-expanded", "false");
  }
  menuBackdrop.hidden = true;
  if (menuPanelContent) {
    menuPanelContent.hidden = true;
  }
}

function renderWeekendLogo() {
  if (!weekendName) {
    return;
  }
  weekendName.innerHTML = `<img class="brand-logo brand-logo--weekend" src="data:image/png;base64," alt="${escapeHtml(state.weekend.name)}" />`;
}

function getProfileName() {
  return sanitizeText(profileNameInput?.value || state.profile?.name || "", 80) || "Lokaal profiel";
}

function getProfileAvatarSource() {
  const uploadedFile = profileAvatarFileInput?.files?.[0];
  if (uploadedFile) {
    if (profileAvatarPreviewUrl) {
      URL.revokeObjectURL(profileAvatarPreviewUrl);
    }
    profileAvatarPreviewUrl = URL.createObjectURL(uploadedFile);
    return profileAvatarPreviewUrl;
  }
  if (profileAvatarPreviewUrl) {
    URL.revokeObjectURL(profileAvatarPreviewUrl);
    profileAvatarPreviewUrl = "";
  }
  return sanitizeImageValue(profileAvatarUrlInput?.value || state.profile?.avatarUrl || "");
}

function avatarMarkup(source, fallback) {
  if (source) {
    return `<img src="${escapeHtml(source)}" alt="">`;
  }
  return escapeHtml(fallback);
}

function renderAccountUi() {
  if (!accountName || !accountStatus || !accountAvatar) {
    return;
  }

  const profileName = getProfileName();
  const avatarSource = getProfileAvatarSource();
  const fallback = profileName.charAt(0).toUpperCase() || "P";
  const statusText = state.auth?.loggedIn
    ? `Ingelogd${state.auth.email ? ` als ${state.auth.email}` : ""}`
    : "Nog niet ingelogd";

  accountName.textContent = profileName;
  accountStatus.textContent = statusText;
  accountAvatar.innerHTML = avatarMarkup(avatarSource, fallback);

  if (accountToggleButton) {
    accountToggleButton.querySelector("span").textContent = state.auth?.loggedIn ? "Uitloggen" : "Inloggen";
  }
  if (accountToggleHint) {
    accountToggleHint.textContent = state.auth?.loggedIn
      ? "Je profiel blijft lokaal klaarstaan voor latere cloud-sync"
      : "Gebruik later Supabase of werk lokaal verder";
  }

  if (profilePreviewAvatar) {
    profilePreviewAvatar.innerHTML = avatarMarkup(avatarSource, fallback);
  }
  if (profilePreviewName) {
    profilePreviewName.textContent = profileName;
  }
  if (profilePreviewState) {
    profilePreviewState.textContent = state.auth?.loggedIn
      ? "Ingelogd profiel, klaar om later met de cloud te synchroniseren"
      : "Nog niet ingelogd, wel klaar voor later accountkoppeling";
  }
}

function openProfileModal() {
  if (!profileModal) return;
  closeMenuPanel();
  if (profileNameInput) profileNameInput.value = state.profile?.name || "";
  if (profileAvatarUrlInput) profileAvatarUrlInput.value = state.profile?.avatarUrl || "";
  if (profileAvatarFileInput) profileAvatarFileInput.value = "";
  renderAccountUi();
  profileModal.hidden = false;
}

function closeProfileModal() {
  if (!profileModal) return;
  profileModal.hidden = true;
  resetCropper();
  if (profileAvatarFileInput) profileAvatarFileInput.value = "";
  if (profileAvatarPreviewUrl) {
    URL.revokeObjectURL(profileAvatarPreviewUrl);
    profileAvatarPreviewUrl = "";
  }
  renderAccountUi();
}

function initCropper(file) {
  const wrap = document.querySelector("#avatar-crop-wrap");
  const img = document.querySelector("#avatar-crop-img");
  const zoom = document.querySelector("#avatar-crop-zoom");
  if (!wrap || !img || !zoom) return;
  const url = URL.createObjectURL(file);
  img.onload = () => {
    URL.revokeObjectURL(url);
    cropNaturalW = img.naturalWidth;
    cropNaturalH = img.naturalHeight;
    cropBaseScale = Math.max(CROP_SIZE / cropNaturalW, CROP_SIZE / cropNaturalH);
    cropScale = cropBaseScale;
    cropOffset = clampCropOffset({
      x: (CROP_SIZE - cropNaturalW * cropScale) / 2,
      y: (CROP_SIZE - cropNaturalH * cropScale) / 2,
    });
    zoom.value = 100;
    applyCropTransform();
    wrap.hidden = false;
  };
  img.src = url;
}

function clampCropOffset(offset) {
  const scaledW = cropNaturalW * cropScale;
  const scaledH = cropNaturalH * cropScale;
  return {
    x: Math.min(Math.max(offset.x, CROP_SIZE - scaledW), 0),
    y: Math.min(Math.max(offset.y, CROP_SIZE - scaledH), 0),
  };
}

function applyCropTransform() {
  const img = document.querySelector("#avatar-crop-img");
  if (img) img.style.transform = `translate(${cropOffset.x}px,${cropOffset.y}px) scale(${cropScale})`;
}

function resetCropper() {
  const wrap = document.querySelector("#avatar-crop-wrap");
  const img = document.querySelector("#avatar-crop-img");
  const zoom = document.querySelector("#avatar-crop-zoom");
  if (wrap) wrap.hidden = true;
  if (img) img.src = "";
  if (zoom) zoom.value = 100;
  cropOffset = { x: 0, y: 0 };
  cropScale = 1;
  cropBaseScale = 1;
  cropNaturalW = 0;
  cropNaturalH = 0;
  cropPointerStart = null;
}

async function getCroppedAvatarBlob() {
  const img = document.querySelector("#avatar-crop-img");
  if (!img || !cropNaturalW) return null;
  const OUT = 400;
  const canvas = document.createElement("canvas");
  canvas.width = OUT;
  canvas.height = OUT;
  const ctx = canvas.getContext("2d");
  ctx.drawImage(img,
    -cropOffset.x / cropScale, -cropOffset.y / cropScale,
    CROP_SIZE / cropScale, CROP_SIZE / cropScale,
    0, 0, OUT, OUT
  );
  return new Promise(resolve => canvas.toBlob(resolve, "image/jpeg", 0.9));
}

async function saveProfile(event) {
  event.preventDefault();
  state.profile.name = sanitizeText(profileNameInput.value, 80);
  state.profile.avatarUrl = sanitizeImageValue(profileAvatarUrlInput?.value || "");

  if (profileAvatarFileInput.files?.[0]) {
    const blob = await getCroppedAvatarBlob();
    state.profile.avatarUrl = await fileToDataUrl(blob || profileAvatarFileInput.files[0]);
  }

  persistAndRender();
  closeProfileModal();
}

function toggleLocalLoginState() {
  state.auth.loggedIn = !state.auth.loggedIn;
  state.auth.provider = state.auth.loggedIn ? "local" : "local";
  state.auth.email = state.auth.loggedIn ? "lokaal-profiel@potzloats.app" : "";
  persistAndRender();
}

function handleCloudSync() {
  window.alert("Cloud-sync staat klaar voor een Supabase-koppeling, maar heeft nog een Supabase URL en anon key nodig.");
}

function renderTabs() {
  tabButtons.forEach((button) => {
    const isActive = button.dataset.tabTarget === activeTab;
    button.classList.toggle("is-active", isActive);
    button.setAttribute("aria-selected", isActive ? "true" : "false");
  });

  tabPanels.forEach((panel) => {
    const isActive = panel.dataset.tabPanel === activeTab;
    panel.classList.toggle("is-active", isActive);
    panel.hidden = !isActive;
  });
}

function renderSummary() {
  const {
    totalInitial,
    totalTopups,
    totalExpenses,
    totalEstimates,
    remaining,
    remainingPerPerson,
    remainingAfterEstimates,
    remainingAfterEstimatesPerPerson,
    participantCount,
  } = calculateSummary();

  const currentCards = [
    {
      label: "Totaal ingelegd",
      value: totalInitial + totalTopups,
      hint: `${currencyFormatter.format(totalInitial)} start en ${currencyFormatter.format(totalTopups)} extra`,
      tone: "positive",
    },
    {
      label: "Uitgegeven",
      value: totalExpenses,
      hint: "Alle definitieve uitgaven samen",
      tone: "expense",
    },
    {
      label: "Openstaande ramingen",
      value: totalEstimates,
      hint: totalEstimates ? "Vooruitblik, telt nog niet mee in saldo" : "Nog geen ramingen open",
      tone: totalEstimates ? "estimate" : "positive",
    },
  ];

  const remainingCards = [
    {
      label: "Resterend budget",
      value: remaining,
      hint: participantCount ? `${participantCount} deelnemers` : "Nog geen deelnemers",
      tone: remaining < 0 ? "negative" : "positive",
    },
    {
      label: "Na ramingen over",
      value: remainingAfterEstimates,
      hint: totalEstimates ? "Definitief saldo minus alle open ramingen" : "Gelijk aan resterend budget",
      tone: remainingAfterEstimates < 0 ? "negative" : "forecast",
    },
    {
      label: "Per persoon over",
      value: remainingPerPerson,
      hint: "Gezamenlijke pot gedeeld door alle deelnemers",
      tone: remainingPerPerson < 0 ? "negative" : "positive",
    },
    {
      label: "Per persoon na ramingen",
      value: remainingAfterEstimatesPerPerson,
      hint: participantCount ? "Rekening houdend met open ramingen" : "Nog geen deelnemers",
      tone: remainingAfterEstimatesPerPerson < 0 ? "negative" : "forecast",
    },
  ];

  const renderCard = (card) => `
    <article class="summary-card summary-card--${card.tone}">
      <p class="summary-card__label">${card.label}</p>
      <p class="summary-card__value">${currencyFormatter.format(card.value)}</p>
      <p class="summary-card__hint">${card.hint}</p>
    </article>
  `;

  summaryCards.innerHTML = `
    <div class="summary-row summary-row--current">
      ${currentCards.map(renderCard).join("")}
    </div>
    <div class="summary-row summary-row--remaining">
      ${remainingCards.map(renderCard).join("")}
    </div>
  `;
}

function renderParticipants() {
  if (!state.participants.length) {
    participantsList.innerHTML = `<p class="muted">Voeg je eerste weekendgenoot toe om te starten.</p>`;
    return;
  }

  participantsList.innerHTML = getSortedParticipants()
    .map((participant) => {
      const contributions = state.contributions.filter((item) => item.participantId === participant.id);
      const initialContribution = contributions.find((item) => item.type === "initial");
      const total = contributions.reduce((sum, item) => sum + item.amount, 0);
      const isEditing = editingParticipantId === participant.id;

      return `
        <article class="person-card ${isEditing ? "person-card--editing" : ""}" data-participant-card="${participant.id}">
          ${participantLogo(participant, "person-card__avatar")}
          <div class="person-card__meta">
            ${
              isEditing
                ? `
                  <div class="inline-edit-grid">
                    <label>
                      Naam
                      <input data-field="name" type="text" value="${escapeHtml(participant.name)}" />
                    </label>
                    <label>
                      Startinleg
                      <input data-field="initial" type="number" min="0" step="0.01" inputmode="decimal" value="${initialContribution?.amount ?? 0}" />
                    </label>
                  </div>
                  <label>
                    Kleur
                    <input data-field="color" type="color" value="${participant.color}" />
                  </label>
                  `
                  : `
                  <strong>${escapeHtml(participant.name)}</strong>
                  <span>${currencyFormatter.format(total)} ingelegd</span>
                `
            }
          </div>
          <div class="person-card__actions">
            ${
              isEditing
                ? `
                  <button class="soft-button" type="button" data-action="save-participant" data-id="${participant.id}">Opslaan</button>
                  <button class="ghost-button ghost-button--small" type="button" data-action="cancel-participant" data-id="${participant.id}">Annuleer</button>
                `
                : `
                  <button class="soft-button" type="button" data-action="edit-participant" data-id="${participant.id}">Wijzig</button>
                  <button class="icon-button" type="button" data-action="remove-participant" data-id="${participant.id}">Verwijder</button>
                `
            }
          </div>
        </article>
      `;
    })
    .join("");
}

function renderTopups() {
  const topups = state.contributions
    .filter((item) => item.type === "topup")
    .sort((a, b) => new Date(b.date) - new Date(a.date));

  if (!topups.length) {
    topupList.innerHTML = `<p class="muted management-empty">Nog geen extra inleg toegevoegd.</p>`;
    return;
  }

  topupList.innerHTML = topups
    .map((topup) => {
      const isEditing = editingTopupId === topup.id;

      return `
          <article class="management-card" data-topup-card="${topup.id}">
            <div class="management-card__logo money-logo" aria-hidden="true">€</div>
            <div class="management-card__meta">
              ${
                isEditing
                  ? `
                    <div class="inline-edit-grid">
                      <label>
                        Bedrag
                        <input data-field="amount" type="number" min="0" step="0.01" value="${topup.amount}" />
                      </label>
                  </div>
                  <label>
                    Notitie
                    <input data-field="note" type="text" value="${escapeHtml(topup.note || "")}" />
                  </label>
                  `
                  : `
                  <strong>Extra inleg ${currencyFormatter.format(topup.amount)}</strong>
                  <span>${formatDate(topup.date)}${topup.note ? ` - ${escapeHtml(topup.note)}` : ""}</span>
                `
              }
          </div>
          <div class="management-card__actions">
            ${
              isEditing
                ? `
                  <button class="soft-button" type="button" data-topup-action="save" data-id="${topup.id}">Opslaan</button>
                  <button class="ghost-button ghost-button--small" type="button" data-topup-action="cancel" data-id="${topup.id}">Annuleer</button>
                `
                : `
                  <button class="soft-button" type="button" data-topup-action="edit" data-id="${topup.id}">Wijzig</button>
                  <button class="icon-button" type="button" data-topup-action="remove" data-id="${topup.id}">Verwijder</button>
                `
            }
          </div>
        </article>
      `;
    })
    .join("");
}

function renderExpenses() {
  const records = [
    ...state.expenses.map((item) => ({ ...item, kind: "expense" })),
    ...state.estimates.map((item) => ({ ...item, amount: getEstimateAmount(item), kind: "estimate" })),
  ].sort((a, b) => new Date(b.date) - new Date(a.date));

  if (!records.length) {
    expenseList.innerHTML = `<p class="muted management-empty">Nog geen uitgaven of ramingen toegevoegd.</p>`;
    return;
  }

  expenseList.innerHTML = records
    .map((record) => {
      const isEditing = editingRecord?.scope === "management" && editingRecord.id === record.id && editingRecord.kind === record.kind;
      const categoryIcon = categoryEmoji[record.category] || categoryEmoji.overig;
      const itemLabel = record.kind === "estimate" ? "Raming" : "Uitgave";
      const detailBits = [categoryLabels[record.category], formatDate(record.date)];
      if (record.kind === "estimate" && record.pricingMode === "per_person") {
        detailBits.push(renderEstimateSummaryText(record));
      }
      if (record.note) detailBits.push(escapeHtml(record.note));

      return `
        <article class="management-card management-card--expense ${record.kind === "estimate" ? "management-card--estimate" : ""}" data-expense-card="${record.id}">
          <div class="management-card__logo" aria-hidden="true">${categoryIcon}</div>
          <div class="management-card__meta">
            ${
              isEditing
                ? renderRecordEditFields(record)
                : `
                  <strong>${itemLabel}: ${escapeHtml(record.description)} - ${currencyFormatter.format(record.amount)}</strong>
                  <span>${detailBits.join(" - ")}</span>
                `
            }
          </div>
          <div class="management-card__actions">
            ${
              isEditing
                ? `
                  <button class="soft-button" type="button" data-expense-action="save" data-kind="${record.kind}" data-id="${record.id}">Opslaan</button>
                  <button class="ghost-button ghost-button--small" type="button" data-expense-action="cancel" data-kind="${record.kind}" data-id="${record.id}">Annuleer</button>
                `
                : `
                  ${record.kind === "estimate" ? `<button class="ghost-button ghost-button--small" type="button" data-expense-action="convert" data-kind="estimate" data-id="${record.id}">Maak definitief</button>` : ""}
                  ${record.kind === "expense" && record.receiptImage ? `<button class="ghost-button ghost-button--small" type="button" data-expense-action="view-receipt" data-kind="expense" data-id="${record.id}">Bon</button>` : ""}
                  <button class="soft-button" type="button" data-expense-action="edit" data-kind="${record.kind}" data-id="${record.id}">Wijzig</button>
                  <button class="icon-button" type="button" data-expense-action="remove" data-kind="${record.kind}" data-id="${record.id}">Verwijder</button>
                `
            }
          </div>
        </article>
      `;
    })
    .join("");
}

function renderTimeline() {
  const categoryFilter = filterCategory.value;
  const entries = [
    ...state.contributions.map((item) => ({
      id: item.id,
      kind: item.type === "initial" ? "contribution" : "topup",
      category: null,
      title: item.type === "initial" ? "Startinleg" : "Extra inleg",
      amount: item.amount,
      personId: item.type === "initial" ? item.participantId : "",
      paidBy: "",
      date: item.date,
      note: item.note,
    })),
    ...state.expenses.map((record) => ({
      id: record.id,
      kind: "expense",
      category: record.category,
      title: record.description,
      amount: record.amount,
      personId: "",
      date: record.date,
      note: record.note,
    })),
    ...state.estimates.map((record) => ({
      id: record.id,
      kind: "estimate",
      category: record.category,
      title: record.description,
      amount: getEstimateAmount(record),
      personId: "",
      pricingMode: record.pricingMode,
      perPersonAmount: record.perPersonAmount,
      participantCountSnapshot: record.participantCountSnapshot,
      date: record.date,
      note: record.note,
    })),
  ]
    .filter((entry) => categoryFilter === "all" || entry.category === categoryFilter)
    .sort((a, b) => new Date(b.date) - new Date(a.date));

  if (!entries.length) {
    timeline.innerHTML = `<p class="muted">Nog geen bewegingen die bij deze filter passen.</p>`;
    return;
  }

  timeline.innerHTML = entries
    .map((entry) => {
      const participant = state.participants.find((person) => person.id === entry.personId);
      const isEditing = editingRecord?.scope === "timeline" && editingRecord.id === entry.id && editingRecord.kind === entry.kind;
      if (isEditing) {
        return renderTimelineEditCard(entry, participant);
      }
      const typeLabel = typeLabels[entry.kind];
      const badgeText = entry.kind === "expense" || entry.kind === "estimate" ? categoryEmoji[entry.category] || categoryEmoji.overig : "\u{1F4B8}";
      const amountClass = entry.kind === "expense" ? "negative" : "positive";
      const amountPrefix = entry.kind === "expense" ? "-" : "+";
      const detailBits = [];
      if (entry.kind === "contribution" && participant) detailBits.push(`Door ${escapeHtml(participant.name)}`);
      if (entry.kind === "expense" || entry.kind === "estimate") {
        detailBits.push(categoryLabels[entry.category] || "Uitgave");
        if (entry.kind === "estimate" && entry.pricingMode === "per_person") {
          detailBits.push(renderEstimateSummaryText(entry));
        }
      }
      detailBits.push(formatDate(entry.date));
      if (entry.note) detailBits.push(escapeHtml(entry.note));

      return `
        <article class="timeline-card ${entry.kind === "estimate" ? "timeline-card--estimate" : ""}" data-timeline-card="${entry.id}">
          <div class="timeline-card__badge ${entry.kind === "expense" || entry.kind === "estimate" ? "" : "participant-logo"}" style="background:${entry.kind === "expense" || entry.kind === "estimate" ? categoryColor(entry.category) : participant?.color || "#102A3A"}">${entry.kind === "expense" || entry.kind === "estimate" ? badgeText : "<span></span>"}</div>
          <div class="timeline-card__main">
            <strong>${escapeHtml(entry.title)}</strong>
            <div class="timeline-card__details">${detailBits.map((bit) => `<span>${bit}</span>`).join("")}</div>
          </div>
          <span class="timeline-card__tag">${typeLabel}</span>
          <div class="timeline-card__actions">
            ${entry.kind === "estimate" ? `<button class="ghost-button ghost-button--small" type="button" data-timeline-action="convert" data-kind="estimate" data-id="${entry.id}">Definitief</button>` : ""}
            <button class="soft-button" type="button" data-timeline-action="edit" data-kind="${entry.kind}" data-id="${entry.id}">Wijzig</button>
            <button class="icon-button" type="button" data-timeline-action="remove" data-kind="${entry.kind}" data-id="${entry.id}">Verwijder</button>
            <span class="timeline-card__amount ${amountClass}">${amountPrefix}${currencyFormatter.format(entry.amount)}</span>
          </div>
        </article>
      `;
    })
    .join("");
}

function saveParticipantEdits(participantId, card) {
  const participant = state.participants.find((item) => item.id === participantId);
  const initialContribution = state.contributions.find((item) => item.participantId === participantId && item.type === "initial");
  if (!participant || !initialContribution || !card) {
    return;
  }

  const name = card.querySelector('[data-field="name"]').value.trim();
  const color = card.querySelector('[data-field="color"]').value;
  const initialAmount = Number(card.querySelector('[data-field="initial"]').value);

  if (!name || !Number.isFinite(initialAmount) || initialAmount < 0) {
    return;
  }

  participant.name = name;
  participant.color = color;
  initialContribution.amount = initialAmount;
  editingParticipantId = null;
  persistAndRender();
}

function saveTopupEdits(topupId, row) {
  const topup = state.contributions.find((item) => item.id === topupId && item.type === "topup");
  if (!topup || !row) {
    return;
  }

  const amount = Number(row.querySelector('[data-field="amount"]').value);
  const note = row.querySelector('[data-field="note"]').value.trim();

  if (!Number.isFinite(amount) || amount <= 0) {
    return;
  }

  topup.participantId = "";
  topup.amount = amount;
  topup.note = note;
  editingTopupId = null;
  persistAndRender();
}

function saveExpenseEdits(expenseId, kind, row) {
  const collection = kind === "estimate" ? state.estimates : state.expenses;
  const expense = collection.find((item) => item.id === expenseId);
  if (!expense || !row) {
    return;
  }

  const description = row.querySelector('[data-field="description"]').value.trim();
  const category = row.querySelector('[data-field="category"]').value;
  const date = row.querySelector('[data-field="date"]').value;
  const note = row.querySelector('[data-field="note"]').value.trim();
  const pricingMode = kind === "estimate" ? row.querySelector('[data-field="pricingMode"]').value : "total";
  const participantCountSnapshot = kind === "estimate" ? Math.max(0, Number(row.querySelector('[data-field="participantCountSnapshot"]').value) || state.participants.length) : 0;
  const perPersonAmount = kind === "estimate" && pricingMode === "per_person"
    ? sanitizeAmount(row.querySelector('[data-field="perPersonAmount"]').value)
    : 0;
  const amount = kind === "estimate" && pricingMode === "per_person"
    ? sanitizeAmount(perPersonAmount * participantCountSnapshot)
    : sanitizeAmount(row.querySelector('[data-field="amount"]').value);

  if (!description || !Number.isFinite(amount) || amount <= 0 || !date) {
    return;
  }

  expense.description = description;
  expense.amount = amount;
  expense.category = category;
  expense.date = date;
  expense.note = note;
  if (kind === "estimate") {
    expense.pricingMode = pricingMode;
    expense.perPersonAmount = pricingMode === "per_person" ? perPersonAmount : 0;
    expense.participantCountSnapshot = pricingMode === "per_person" ? participantCountSnapshot : 0;
  }
  editingRecord = null;
  persistAndRender();
}

function calculateSummary() {
  const totalInitial = state.contributions
    .filter((item) => item.type === "initial")
    .reduce((sum, item) => sum + item.amount, 0);

  const totalTopups = state.contributions
    .filter((item) => item.type === "topup")
    .reduce((sum, item) => sum + item.amount, 0);

  const totalExpenses = state.expenses.reduce((sum, item) => sum + item.amount, 0);
  const totalEstimates = state.estimates.reduce((sum, item) => sum + getEstimateAmount(item), 0);
  const remaining = totalInitial + totalTopups - totalExpenses;
  const remainingAfterEstimates = remaining - totalEstimates;
  const participantCount = state.participants.length;
  const remainingPerPerson = participantCount ? remaining / participantCount : 0;
  const remainingAfterEstimatesPerPerson = participantCount ? remainingAfterEstimates / participantCount : 0;

  return {
    totalInitial,
    totalTopups,
    totalExpenses,
    totalEstimates,
    remaining,
    remainingPerPerson,
    remainingAfterEstimates,
    remainingAfterEstimatesPerPerson,
    participantCount,
  };
}

async function collectExpenseForm() {
  const kind = expenseKindInput.value;
  const description = expenseDescriptionInput.value.trim();
  const category = expenseCategoryInput.value;
  const date = expenseDateInput.value;
  const note = expenseNoteInput.value.trim();
  const pricingMode = kind === "estimate" ? estimatePricingModeInput.value : "total";
  const participantCountSnapshot = kind === "estimate" && pricingMode === "per_person" ? state.participants.length : 0;
  const perPersonAmount = kind === "estimate" && pricingMode === "per_person"
    ? sanitizeAmount(estimatePerPersonAmountInput?.value)
    : 0;
  const amount = kind === "estimate" && pricingMode === "per_person"
    ? sanitizeAmount(perPersonAmount * participantCountSnapshot)
    : sanitizeAmount(expenseAmountInput.value);

  if (kind === "estimate" && pricingMode === "per_person" && participantCountSnapshot < 1) {
    window.alert("Voeg eerst minimaal 1 deelnemer toe voordat je een raming per persoon opslaat.");
    return null;
  }

  if (!description || !Number.isFinite(amount) || amount <= 0 || !date) {
    return null;
  }

  const receiptImage = kind === "expense"
    ? pendingReceiptImage || (expenseReceiptInput.files[0] ? await fileToDataUrl(expenseReceiptInput.files[0]) : "")
    : "";

  return {
    id: createId(),
    kind,
    description,
    amount,
    category,
    date,
    note,
    receiptImage,
    ocrStatus: receiptImage ? "reviewed" : "manual",
    pricingMode,
    perPersonAmount,
    participantCountSnapshot,
  };
}

function showReceiptReview(message, status) {
  ocrMessage.textContent = message;
  ocrStatus.textContent = status.replace(/_/g, " ");
  if (receiptPreviewImage) {
    receiptPreviewImage.src = pendingReceiptImage || "";
  }
  receiptReview.hidden = false;
}

async function requestReceiptAnalysis(payload) {
  if (location.protocol !== "file:") {
    try {
      const response = await fetch("/api/receipt/analyze", {
        method: "POST",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify(payload),
      });
      const result = await response.json();
      if (!response.ok) {
        throw new Error(result.error || "Bonanalyse mislukt.");
      }
      return result;
    } catch (error) {
      return analyzeReceiptLocally(payload, true);
    }
  }

  return analyzeReceiptLocally(payload, false);
}

function analyzeReceiptLocally(payload, serverFailed) {
  const combined = `${payload.fileName || ""} ${payload.notesHint || ""}`.trim();
  const amount = parseAmountFromText(combined);

  return {
    amount,
    date: parseDateFromText(combined) || todayIso(),
    description: prettifyReceiptName(payload.fileName || ""),
    category: inferCategory(combined),
    confidence: amount ? 0.44 : 0.16,
    ocrStatus: amount ? "suggested" : "manual_required",
    message: amount
      ? serverFailed
        ? "Serveranalyse was niet beschikbaar, dus ik heb lokaal een voorzichtige suggestie gemaakt. Controleer vooral het bedrag bij 'te betalen'."
        : "Lokale suggestie gemaakt. Controleer vooral het bedrag bij 'te betalen' of 'totaal'."
      : "Ik kon geen betrouwbaar bedrag herkennen. Vergroot de bon en vul het juiste bedrag handmatig in.",
  };
}

function parseAmountFromText(text) {
  const prioritized = extractKeywordAmount(text);
  if (prioritized !== null) {
    return prioritized;
  }

  const withoutDate = text.replace(/(20\d{2})[-_ ]?(0[1-9]|1[0-2])[-_ ]?([0-2]\d|3[01])/g, " ");
  const normalized = withoutDate.replace(/,/g, ".").replace(/[^0-9.]/g, " ");
  const matches = normalized.match(/\d+(?:\.\d{1,2})?/g) || [];
  const values = matches
    .map((value) => Number(value))
    .filter((value) => Number.isFinite(value) && value > 0 && value < 10000);

  if (!values.length) {
    return null;
  }

  const decimalMatches = matches.filter((value) => value.includes(".")).map((value) => Number(value));
  if (decimalMatches.length) {
    return decimalMatches.sort((a, b) => a - b)[0];
  }

  return values.sort((a, b) => a - b)[0];
}

function extractKeywordAmount(text) {
  const normalized = text.toLowerCase().replace(/,/g, ".");
  const patterns = [
    /te betalen[^0-9]{0,12}(\d+(?:\.\d{1,2})?)/,
    /totaal[^0-9]{0,12}(\d+(?:\.\d{1,2})?)/,
    /total[^0-9]{0,12}(\d+(?:\.\d{1,2})?)/,
    /amount due[^0-9]{0,12}(\d+(?:\.\d{1,2})?)/,
    /netto[^0-9]{0,12}(\d+(?:\.\d{1,2})?)/,
    /(\d+(?:\.\d{1,2})?)[^a-z0-9]{0,12}netto/,
    /euro[^0-9]{0,12}(\d+(?:\.\d{1,2})?)/,
    /(\d+(?:\.\d{1,2})?)[^a-z0-9]{0,12}euro/,
    /eur[^0-9]{0,12}(\d+(?:\.\d{1,2})?)/,
    /(\d+(?:\.\d{1,2})?)[^a-z0-9]{0,12}eur/,
    /€[^0-9]{0,12}(\d+(?:\.\d{1,2})?)/,
    /(\d+(?:\.\d{1,2})?)[^a-z0-9]{0,12}€/,
  ];

  for (const pattern of patterns) {
    const match = normalized.match(pattern);
    if (match) {
      const amount = Number(match[1]);
      if (Number.isFinite(amount) && amount > 0 && amount < 10000) {
        return amount;
      }
    }
  }

  return null;
}

function parseDateFromText(text) {
  const match = text.match(/(20\d{2})[-_ ]?(0[1-9]|1[0-2])[-_ ]?([0-2]\d|3[01])/);
  if (!match) {
    return null;
  }

  return `${match[1]}-${match[2]}-${match[3]}`;
}

function prettifyReceiptName(fileName) {
  const base = fileName
    .replace(/\.[a-z0-9]+$/i, "")
    .replace(/[_-]+/g, " ")
    .replace(/\s+/g, " ")
    .trim();

  if (!base) {
    return "Bonnetje";
  }

  return base.replace(/\b\w/g, (char) => char.toUpperCase());
}

function inferCategory(text) {
  const lower = text.toLowerCase();
  if (/(hotel|huis|villa|bnb|stay|accommod)/.test(lower)) return "accommodatie";
  if (/(supermarkt|eten|diner|lunch|ontbijt|snack|bbq|restaurant)/.test(lower)) return "eten";
  if (/(bar|bier|wijn|drank)/.test(lower)) return "drinken";
  if (/(bowling|escape|boot|museum|activiteit|tickets)/.test(lower)) return "activiteit";
  if (/(taxi|ov|trein|bus|benzine|parkeren|vervoer)/.test(lower)) return "vervoer";
  return "overig";
}

function openReceiptModal(imageSource) {
  receiptModalImage.src = imageSource;
  receiptModal.hidden = false;
}

function closeReceiptModal() {
  receiptModal.hidden = true;
  receiptModalImage.src = "";
}

async function exportStateToFile() {
  const payload = {
    exportedAt: new Date().toISOString(),
    app: "Pot z,n Loatst",
    data: state,
  };
  const fileName = `potzloats-${todayIso()}.json`;
  const json = JSON.stringify(payload, null, 2);
  const blob = new Blob([json], { type: "application/json" });

  if (typeof File === "function" && navigator.share && navigator.canShare) {
    try {
      const shareFile = new File([blob], fileName, { type: "application/json" });
      if (navigator.canShare({ files: [shareFile] })) {
        await navigator.share({
          files: [shareFile],
          title: "Pot z,n Loatst export",
          text: "Bewaar of deel je potbestand.",
        });
        return;
      }
    } catch (error) {
      console.warn("Delen van exportbestand mislukt, probeer downloadfallback.", error);
    }
  }

  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  link.rel = "noopener";
  document.body.append(link);
  link.click();
  link.remove();

  window.setTimeout(() => URL.revokeObjectURL(url), 1000);

  if (/iPad|iPhone|iPod/.test(navigator.userAgent) && !navigator.share) {
    window.open(url, "_blank", "noopener");
  }
}

async function importStateFromFile(event) {
  const file = event.target.files?.[0];
  if (!file) {
    return;
  }

  try {
    const text = await readFileAsText(file);
    const parsed = JSON.parse(text);
    const nextValue = parsed && typeof parsed === "object" ? parsed.data || parsed : null;
    if (!nextValue || typeof nextValue !== "object" || Array.isArray(nextValue)) {
      throw new Error("Ongeldig bestand");
    }
    state = normalizeState(nextValue);
    resetUiState();
    persistAndRender();
  } catch (error) {
    window.alert("Kon dit bestand niet inlezen als Pot z,n Loatst-data.");
  } finally {
    if (importStateFileInput) importStateFileInput.value = "";
  }
}

function resetUiState() {
  pendingReceiptImage = "";
  editingParticipantId = null;
  editingTopupId = null;
  editingRecord = null;
  activeTab = "uitgaven";
  closeReceiptModal();
  resetExpenseComposer();
}

function resetExpenseComposer() {
  expenseForm.reset();
  expenseKindInput.value = "expense";
  estimatePricingModeInput.value = "total";
  expenseDateInput.value = todayIso();
  pendingReceiptImage = "";
  receiptReview.hidden = true;
  renderExpenseComposerState();
}

function getSortedParticipants() {
  return state.participants
    .slice()
    .sort((a, b) => a.name.localeCompare(b.name, "nl", { sensitivity: "base" }));
}

function renderRecordEditFields(record) {
  const pricingMode = record.pricingMode === "per_person" ? "per_person" : "total";
  const participantCountSnapshot = pricingMode === "per_person" ? Math.max(1, Number(record.participantCountSnapshot) || state.participants.length || 1) : 0;
  const perPersonAmount = pricingMode === "per_person"
    ? sanitizeAmount(record.perPersonAmount || (participantCountSnapshot ? record.amount / participantCountSnapshot : 0))
    : 0;
  return `
    <div class="inline-edit-grid">
      <label>
        Omschrijving
        <input data-field="description" type="text" value="${escapeHtml(record.description)}" />
      </label>
      <label>
        Bedrag
        <input data-field="amount" type="number" min="0" step="0.01" inputmode="decimal" value="${record.amount}" />
      </label>
    </div>
    <div class="inline-edit-grid">
      <label>
        Categorie
        <select data-field="category">
          ${Object.entries(categoryLabels)
            .map(([value, label]) => `<option value="${value}" ${record.category === value ? "selected" : ""}>${label}</option>`)
            .join("")}
        </select>
      </label>
      ${
        record.kind === "estimate"
          ? `
            <label>
              Ramingmodus
              <select data-field="pricingMode">
                <option value="total" ${pricingMode === "total" ? "selected" : ""}>Totaalbedrag</option>
                <option value="per_person" ${pricingMode === "per_person" ? "selected" : ""}>Bedrag per persoon</option>
              </select>
            </label>
          `
          : ""
      }
    </div>
    ${
      record.kind === "estimate"
        ? `
          <div class="inline-edit-grid">
            <label data-per-person-group ${pricingMode === "per_person" ? "" : 'hidden'}>
              Bedrag per persoon
              <input data-field="perPersonAmount" type="number" min="0" step="0.01" inputmode="decimal" value="${perPersonAmount || ""}" />
            </label>
            <label data-per-person-group ${pricingMode === "per_person" ? "" : 'hidden'}>
              Aantal deelnemers
              <input data-field="participantCountSnapshot" type="number" min="1" step="1" value="${participantCountSnapshot || ""}" />
            </label>
          </div>
          <p class="field-help" data-per-person-summary ${pricingMode === "per_person" ? "" : 'hidden'}>${renderEstimateSummaryText({ pricingMode, perPersonAmount, participantCountSnapshot, amount: record.amount })}</p>
        `
        : ""
    }
    <div class="inline-edit-grid">
      <label>
        Datum
        <input data-field="date" type="date" value="${record.date}" />
      </label>
      <label>
        Notitie
        <input data-field="note" type="text" value="${escapeHtml(record.note || "")}" />
      </label>
    </div>
  `;
}

function renderTimelineEditCard(entry, participant) {
  const typeLabel = typeLabels[entry.kind];
  const amountPrefix = entry.kind === "expense" ? "-" : "+";
  const amountClass = entry.kind === "expense" ? "negative" : "positive";

  if (entry.kind === "contribution" || entry.kind === "topup") {
    return `
      <article class="timeline-card timeline-card--editing" data-timeline-card="${entry.id}">
        <div class="timeline-card__badge ${entry.kind === "topup" ? "" : "participant-logo"}" style="background:${entry.kind === "topup" ? "#7A8446" : participant?.color || "#102A3A"}">${entry.kind === "topup" ? "€" : "<span></span>"}</div>
        <div class="timeline-card__main">
          <div class="inline-edit-grid">
            <label>
              Bedrag
              <input data-field="amount" type="number" min="0" step="0.01" inputmode="decimal" value="${entry.amount}" />
            </label>
            <label>
              Datum
              <input data-field="date" type="date" value="${entry.date}" />
            </label>
          </div>
          <label>
            Notitie
            <input data-field="note" type="text" value="${escapeHtml(entry.note || "")}" />
          </label>
        </div>
        <span class="timeline-card__tag">${typeLabel}</span>
        <div class="timeline-card__actions">
          <button class="soft-button" type="button" data-timeline-action="save" data-kind="${entry.kind}" data-id="${entry.id}">Opslaan</button>
          <button class="ghost-button ghost-button--small" type="button" data-timeline-action="cancel" data-kind="${entry.kind}" data-id="${entry.id}">Annuleer</button>
          <span class="timeline-card__amount ${amountClass}">${amountPrefix}${currencyFormatter.format(entry.amount)}</span>
        </div>
      </article>
    `;
  }

  return `
    <article class="timeline-card timeline-card--editing ${entry.kind === "estimate" ? "timeline-card--estimate" : ""}" data-timeline-card="${entry.id}">
      <div class="timeline-card__badge" style="background:${categoryColor(entry.category)}">${categoryEmoji[entry.category] || categoryEmoji.overig}</div>
      <div class="timeline-card__main">
        ${renderRecordEditFields(entry)}
      </div>
      <span class="timeline-card__tag">${typeLabel}</span>
      <div class="timeline-card__actions">
        <button class="soft-button" type="button" data-timeline-action="save" data-kind="${entry.kind}" data-id="${entry.id}">Opslaan</button>
        <button class="ghost-button ghost-button--small" type="button" data-timeline-action="cancel" data-kind="${entry.kind}" data-id="${entry.id}">Annuleer</button>
        <span class="timeline-card__amount ${amountClass}">${amountPrefix}${currencyFormatter.format(entry.amount)}</span>
      </div>
    </article>
  `;
}

function saveTimelineEdits(kind, id, row) {
  if (kind === "contribution" || kind === "topup") {
    const item = state.contributions.find((entry) => entry.id === id);
    if (!item || !row) return;
    const amount = Number(row.querySelector('[data-field="amount"]').value);
    const date = row.querySelector('[data-field="date"]').value;
    const note = row.querySelector('[data-field="note"]').value.trim();
    if (!Number.isFinite(amount) || amount < 0 || !date) return;
    item.amount = amount;
    item.date = date;
    item.note = note;
    editingRecord = null;
    persistAndRender();
    return;
  }

  saveExpenseEdits(id, kind, row);
}

function removeRecord(kind, id) {
  if (kind === "contribution" || kind === "topup") {
    state.contributions = state.contributions.filter((item) => item.id !== id);
  } else if (kind === "estimate") {
    state.estimates = state.estimates.filter((item) => item.id !== id);
  } else {
    state.expenses = state.expenses.filter((item) => item.id !== id);
  }

  if (editingRecord?.id === id && editingRecord?.kind === kind) {
    editingRecord = null;
  }
}

function convertEstimateToExpense(id) {
  const estimate = state.estimates.find((item) => item.id === id);
  if (!estimate) return;

  state.expenses.unshift({
    id: createId(),
    description: estimate.description,
    amount: estimate.amount,
    category: estimate.category,
    date: estimate.date,
    note: estimate.note,
    receiptImage: "",
    ocrStatus: "manual",
  });
  state.estimates = state.estimates.filter((item) => item.id !== id);
  if (editingRecord?.id === id && editingRecord?.kind === "estimate") {
    editingRecord = null;
  }
  persistAndRender();
}

function participantLogo(participant, className) {
  const color = participant?.color || "#102A3A";
  const label = participant?.name ? `Logo van ${participant.name}` : "Deelnemerlogo";
  return `
    <div class="${className} participant-logo" style="background:${color}" aria-label="${escapeHtml(label)}" title="${escapeHtml(label)}">
      <span></span>
    </div>
  `;
}

function formatDate(value) {
  return dateFormatter.format(new Date(value));
}

function escapeHtml(value) {
  return String(value)
    .replaceAll("&", "&amp;")
    .replaceAll("<", "&lt;")
    .replaceAll(">", "&gt;")
    .replaceAll('"', "&quot;");
}

function fallbackColor(index) {
  return ["#102A3A", "#7A8446", "#D6A63A", "#B86B45", "#3F4932"][index % 5];
}

function categoryColor(category) {
  return {
    accommodatie: "#102A3A",
    eten: "#B86B45",
    drinken: "#D6A63A",
    activiteit: "#7A8446",
    vervoer: "#3F4932",
    overig: "#7A8446",
  }[category] || "#7A8446";
}

function todayIso() {
  return new Date().toISOString().slice(0, 10);
}

function fileToDataUrl(file) {
  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(reader.result);
    reader.onerror = () => reject(new Error("Kon de bonfoto niet lezen."));
    reader.readAsDataURL(file);
  });
}

function readFileAsText(file) {
  if (typeof file.text === "function") {
    return file.text();
  }

  return new Promise((resolve, reject) => {
    const reader = new FileReader();
    reader.onload = () => resolve(String(reader.result || ""));
    reader.onerror = () => reject(new Error("Kon dit bestand niet lezen."));
    reader.readAsText(file);
  });
}

function registerServiceWorker() {
  if (!("serviceWorker" in navigator) || location.protocol === "file:") {
    return;
  }

  window.addEventListener("load", async () => {
    try {
      await navigator.serviceWorker.register("./sw.js");
    } catch (error) {
      console.warn("Service worker registreren mislukt:", error);
    }
  });
}

function readFromStorage(key) {
  try {
    return localStorage.getItem(key);
  } catch (error) {
    console.warn("Lokale opslag lezen mislukt:", error);
    return null;
  }
}

function writeToStorage(key, value) {
  try {
    localStorage.setItem(key, value);
  } catch (error) {
    console.warn("Lokale opslag bewaren mislukt:", error);
  }
}

function sanitizeText(value, maxLength = 240) {
  return String(value || "").replace(/[\u0000-\u001F\u007F]/g, "").trim().slice(0, maxLength);
}

function sanitizeAmount(value) {
  const amount = Number(value);
  if (!Number.isFinite(amount)) {
    return 0;
  }
  return Math.max(0, Math.min(999999, Math.round(amount * 100) / 100));
}

function sanitizeDate(value) {
  return /^\d{4}-\d{2}-\d{2}$/.test(String(value || "")) ? value : todayIso();
}

function sanitizeImageValue(value) {
  const nextValue = String(value || "");
  if (!nextValue) {
    return "";
  }
  return /^(data:image\/|blob:|https?:\/\/|\.\/|\/)/.test(nextValue) ? nextValue : "";
}

function normalizeEstimate(item, participantCount) {
  const pricingMode = item.pricingMode === "per_person" ? "per_person" : "total";
  const snapshot = pricingMode === "per_person"
    ? Math.max(1, Number(item.participantCountSnapshot) || participantCount || 1)
    : 0;
  const perPersonAmount = pricingMode === "per_person"
    ? sanitizeAmount(item.perPersonAmount || (snapshot ? Number(item.amount) / snapshot : 0))
    : 0;
  const amount = pricingMode === "per_person"
    ? sanitizeAmount(perPersonAmount * snapshot)
    : sanitizeAmount(item.amount);

  return {
    id: item.id || createId(),
    description: sanitizeText(item.description) || "Raming",
    amount,
    category: categoryLabels[item.category] ? item.category : "overig",
    paidBy: sanitizeText(item.paidBy),
    date: sanitizeDate(item.date),
    note: sanitizeText(item.note),
    pricingMode,
    perPersonAmount,
    participantCountSnapshot: snapshot,
  };
}

function normalizeState(rawState) {
  const nextState = rawState && typeof rawState === "object" ? rawState : {};
  const participants = Array.isArray(nextState.participants) ? nextState.participants : [];
  const contributions = Array.isArray(nextState.contributions) ? nextState.contributions : [];
  const expenses = Array.isArray(nextState.expenses) ? nextState.expenses : [];
  const estimates = Array.isArray(nextState.estimates) ? nextState.estimates : [];

  return {
    weekend: {
      name: nextState.weekend?.name || "Op z'n Loatst",
      appName: nextState.weekend?.appName || "Pot z,n Loatst",
    },
    auth: {
      loggedIn: Boolean(nextState.auth?.loggedIn),
      provider: sanitizeText(nextState.auth?.provider || "local", 40) || "local",
      email: sanitizeText(nextState.auth?.email || "", 120),
      userId: sanitizeText(nextState.auth?.userId || "", 80),
      lastSyncedAt: sanitizeText(nextState.auth?.lastSyncedAt || "", 80),
    },
    profile: {
      name: sanitizeText(nextState.profile?.name || "", 80),
      avatarUrl: sanitizeImageValue(nextState.profile?.avatarUrl || ""),
    },
    participants: participants.map((participant, index) => ({
      id: participant.id || createId(),
      name: sanitizeText(participant.name) || `Deelnemer ${index + 1}`,
      color: participant.color || fallbackColor(index),
    })),
    contributions: contributions
      .filter((item) => item && typeof item === "object")
      .map((item) => ({
        id: item.id || createId(),
        participantId: item.type === "topup" ? "" : sanitizeText(item.participantId || "", 80),
        amount: sanitizeAmount(item.amount),
        type: item.type === "topup" ? "topup" : "initial",
        note: sanitizeText(item.note),
        date: sanitizeDate(item.date),
      })),
    expenses: expenses
      .filter((item) => item && typeof item === "object")
      .map((item) => ({
        id: item.id || createId(),
        description: sanitizeText(item.description) || "Uitgave",
        amount: sanitizeAmount(item.amount),
        category: categoryLabels[item.category] ? item.category : "overig",
        paidBy: sanitizeText(item.paidBy),
        date: sanitizeDate(item.date),
        note: sanitizeText(item.note),
        receiptImage: sanitizeImageValue(item.receiptImage),
        receiptPath: sanitizeText(item.receiptPath || "", 240),
        ocrStatus: sanitizeText(item.ocrStatus || "manual", 40) || "manual",
      })),
    estimates: estimates
      .filter((item) => item && typeof item === "object")
      .map((item) => normalizeEstimate(item, participants.length)),
  };
}

function createEmptyState() {
  return normalizeState({
    weekend: {
      name: "Op z'n Loatst",
      appName: "Pot z,n Loatst",
    },
    auth: {
      loggedIn: false,
      provider: "local",
      email: "",
      userId: "",
      lastSyncedAt: "",
    },
    profile: {
      name: "",
      avatarUrl: "",
    },
    participants: [],
    contributions: [],
    expenses: [],
    estimates: [],
  });
}

function loadState() {
  const savedState = readFromStorage(primaryStorageKey) || readFromStorage(storageKey);
  if (!savedState) {
    return normalizeState(cloneData(demoState));
  }

  try {
    return normalizeState(JSON.parse(savedState));
  } catch (error) {
    return normalizeState(cloneData(demoState));
  }
}

function persistAndRender() {
  writeToStorage(primaryStorageKey, JSON.stringify(state));
  writeToStorage(storageKey, JSON.stringify(state));
  render();
  if (!cloudHydrating) {
    queueCloudSync("local-change");
  }
}

function getSupabaseConfig() {
  const config = globalThis.POTZLOATS_CONFIG || {};
  return {
    supabaseUrl: sanitizeText(config.supabaseUrl || "", 240),
    supabaseAnonKey: sanitizeText(config.supabaseAnonKey || "", 2048),
    mediaBucket: sanitizeText(config.mediaBucket || "potzloats-media", 120) || "potzloats-media",
  };
}

function isSupabaseConfigured() {
  const config = getSupabaseConfig();
  return Boolean(config.supabaseUrl && config.supabaseAnonKey && globalThis.supabase?.createClient);
}

function getSupabaseClient() {
  if (!isSupabaseConfigured()) {
    return null;
  }

  if (!supabaseClientInstance) {
    const config = getSupabaseConfig();
    supabaseClientInstance = globalThis.supabase.createClient(config.supabaseUrl, config.supabaseAnonKey, {
      auth: {
        persistSession: true,
        autoRefreshToken: true,
        detectSessionInUrl: true,
      },
    });
  }

  return supabaseClientInstance;
}

function hasMeaningfulState(candidateState) {
  return Boolean(
    candidateState?.participants?.length ||
    candidateState?.contributions?.length ||
    candidateState?.expenses?.length ||
    candidateState?.estimates?.length ||
    candidateState?.profile?.name ||
    candidateState?.profile?.avatarUrl
  );
}

function getMigrationMap() {
  try {
    const raw = readFromStorage(migrationStorageKey);
    const parsed = raw ? JSON.parse(raw) : {};
    return parsed && typeof parsed === "object" ? parsed : {};
  } catch (error) {
    return {};
  }
}

function markMigrationDone(userId) {
  const map = getMigrationMap();
  map[userId] = new Date().toISOString();
  writeToStorage(migrationStorageKey, JSON.stringify(map));
}

function wasMigrationDone(userId) {
  return Boolean(getMigrationMap()[userId]);
}

function renderAccountUi() {
  if (!accountName || !accountStatus || !accountAvatar) {
    return;
  }

  const profileName = getProfileName();
  const avatarSource = getProfileAvatarSource();
  const fallback = profileName.charAt(0).toUpperCase() || "P";
  const cloudReady = isSupabaseConfigured();
  const lastSyncText = state.auth?.lastSyncedAt
    ? ` · laatste sync ${dateFormatter.format(new Date(state.auth.lastSyncedAt))}`
    : "";
  const statusText = state.auth?.loggedIn
    ? `Ingelogd${state.auth.email ? ` als ${state.auth.email}` : ""}${lastSyncText}`
    : cloudReady
      ? "Lokale modus, cloud staat klaar"
      : "Lokale modus, Supabase nog niet ingesteld";

  accountName.textContent = profileName;
  accountStatus.textContent = statusText;
  accountAvatar.innerHTML = avatarMarkup(avatarSource, fallback);

  if (accountLoginButton) {
    accountLoginButton.textContent = state.auth?.loggedIn ? "Uitloggen" : "Inloggen";
  }

  if (syncCloudButton) {
    const syncNode = syncCloudButton.querySelector("span");
    if (syncNode) {
      syncNode.textContent = state.auth?.loggedIn
        ? "Nu synchroniseren"
        : cloudReady
          ? "Cloud instellen"
          : "Supabase koppelen";
    }
  }

  if (profilePreviewAvatar) {
    profilePreviewAvatar.innerHTML = avatarMarkup(avatarSource, fallback);
  }
  if (profilePreviewName) {
    profilePreviewName.textContent = profileName;
  }
  if (profilePreviewState) {
    profilePreviewState.textContent = state.auth?.loggedIn
      ? "Ingelogd profiel, wijzigingen worden ook met je account gesynchroniseerd"
      : cloudReady
        ? "Nog niet ingelogd, maar online sync staat klaar"
        : "Nog niet ingelogd, lokale modus blijft beschikbaar";
  }

  const authStatus = document.querySelector("#auth-status");
  if (authStatus && authStatus.textContent.trim() === authStatusFallback) {
    authStatus.textContent = cloudReady
      ? "Log in om je deelnemers, inleg, uitgaven en bonnetjes online te bewaren."
      : authStatusFallback;
  }
}

function openAuthModal(prefillEmail = "") {
  const authModal = document.querySelector("#auth-modal");
  const emailInput = document.querySelector("#auth-email");
  const passwordInput = document.querySelector("#auth-password");
  if (!authModal || !emailInput || !passwordInput) return;

  closeMenuPanel();
  emailInput.value = prefillEmail || state.auth?.email || "";
  passwordInput.value = "";
  const statusNode = document.querySelector("#auth-status");
  if (statusNode) { statusNode.textContent = ""; statusNode.hidden = true; }
  authModal.hidden = false;
  bindAuthModal();
}

function closeAuthModal() {
  const authModal = document.querySelector("#auth-modal");
  if (authModal) {
    authModal.hidden = true;
  }
}

function setAuthStatus(message, isError = false) {
  const statusNode = document.querySelector("#auth-status");
  if (!statusNode) return;
  statusNode.textContent = message;
  statusNode.hidden = !message;
  statusNode.style.color = isError ? "#8C3C2A" : "";
}

async function submitAuth(mode) {
  const client = getSupabaseClient();
  if (!client) {
    setAuthStatus("Vul eerst `supabase-config.js` in met je Supabase URL en anon key.", true);
    return;
  }

  const emailInput = document.querySelector("#auth-email");
  const passwordInput = document.querySelector("#auth-password");
  const displayNameInput = document.querySelector("#auth-display-name");
  const email = sanitizeText(emailInput?.value || "", 120);
  const password = String(passwordInput?.value || "");
  const displayName = sanitizeText(state.profile?.name || "", 80);

  if (!email || password.length < 6) {
    setAuthStatus("Vul een geldig e-mailadres en een wachtwoord van minimaal 6 tekens in.", true);
    return;
  }

  setAuthStatus(mode === "signup" ? "Account wordt aangemaakt..." : "Inloggen...");

  try {
    if (mode === "signup") {
      const { data, error } = await client.auth.signUp({
        email,
        password,
        options: {
          data: {
            display_name: displayName,
          },
        },
      });
      if (error) {
        throw error;
      }

      if (displayName) {
        state.profile.name = displayName;
      }

      if (data?.session?.user) {
        await saveProfileToCloud(data.session.user);
        setAuthStatus("Account aangemaakt. Je bent ingelogd en je data wordt nu gesynchroniseerd.");
        closeAuthModal();
      } else {
        setAuthStatus("Account aangemaakt. Bevestig je e-mail en log daarna in.");
      }
      renderAccountUi();
      return;
    }

    const signInPromise = client.auth.signInWithPassword({ email, password });
    const timeoutPromise = new Promise((_, reject) =>
      setTimeout(() => reject(new Error("Inloggen duurt te lang. Controleer je verbinding en probeer opnieuw.")), 15000)
    );
    const { data, error } = await Promise.race([signInPromise, timeoutPromise]);
    if (error) {
      throw error;
    }

    setAuthStatus("Ingelogd. Je gegevens worden geladen.");
    closeAuthModal();
  } catch (error) {
    setAuthStatus(error?.message || "Inloggen is mislukt.", true);
  }
}

function bindAuthModal() {
  if (authModalBound) return;
  authModalBound = true;

  const authForm = document.querySelector("#auth-form");
  const authSignUpButton = document.querySelector("#auth-sign-up");
  const closeAuthButton = document.querySelector("#close-auth");
  const authModal = document.querySelector("#auth-modal");
  const pwToggle = document.querySelector("#auth-password-toggle");
  const pwInput = document.querySelector("#auth-password");

  authForm?.addEventListener("submit", async (event) => {
    event.preventDefault();
    await submitAuth("signin");
  });

  authSignUpButton?.addEventListener("click", async () => {
    await submitAuth("signup");
  });

  pwToggle?.addEventListener("click", () => {
    if (!pwInput) return;
    const show = pwInput.type === "password";
    pwInput.type = show ? "text" : "password";
    pwToggle.textContent = show ? "\u{1F648}" : "\u{1F441}";
    pwToggle.setAttribute("aria-label", show ? "Wachtwoord verbergen" : "Wachtwoord tonen");
  });

  closeAuthButton?.addEventListener("click", closeAuthModal);
  authModal?.addEventListener("click", (event) => {
    if (event.target?.dataset?.closeAuth === "true") closeAuthModal();
  });
}

async function getCurrentSessionUser() {
  const client = getSupabaseClient();
  if (!client) {
    return null;
  }

  const { data, error } = await client.auth.getUser();
  if (error) {
    console.warn("Gebruiker ophalen uit Supabase mislukte:", error);
    return null;
  }

  return data?.user || null;
}

async function toggleLocalLoginState() {
  if (state.auth?.loggedIn) {
    state = createEmptyState();
    writeToStorage(primaryStorageKey, JSON.stringify(state));
    writeToStorage(storageKey, JSON.stringify(state));
    render();

    // Sign out locally with a short timeout so a slow network never wedges
    // the supabase-js auth lock. scope:'local' skips the server call which
    // is the operation most likely to hang and hold the lock.
    const oldClient = supabaseClientInstance;
    if (oldClient) {
      try {
        await Promise.race([
          oldClient.auth.signOut({ scope: "local" }),
          new Promise((_, reject) => setTimeout(() => reject(new Error("signOut timeout")), 3000)),
        ]);
      } catch (_) {}
    }

    // Hard reset: discard the GoTrueClient and rebuild from scratch. This
    // guarantees no stuck Web Lock, refresh-token timer, or stale session
    // carries over into the next sign-in attempt.
    supabaseClientInstance = null;
    authStateListenerBound = false;

    // Defensive: clear any residual supabase auth keys in localStorage
    // (session JWT, refresh token, PKCE code verifier, etc.)
    try {
      const toRemove = [];
      for (let i = 0; i < localStorage.length; i++) {
        const key = localStorage.key(i);
        if (key && key.startsWith("sb-")) toRemove.push(key);
      }
      toRemove.forEach((k) => localStorage.removeItem(k));
    } catch (_) {}

    // Re-create the client and rebind the auth-state listener
    await bootstrapCloudFeatures();
    return;
  }

  const client = getSupabaseClient();
  if (!client) {
    window.alert("Supabase is nog niet ingesteld. Vul eerst supabase-config.js in.");
    return;
  }
  openAuthModal();
}

async function handleCloudSync() {
  if (!isSupabaseConfigured()) {
    openAuthModal();
    window.alert("Vul eerst `supabase-config.js` in met je Supabase URL en anon key. Daarna werkt online sync meteen.");
    return;
  }

  const user = await getCurrentSessionUser();
  if (!user) {
    openAuthModal();
    return;
  }

  try {
    await syncStateToCloud("manual");
    window.alert("De weekendpot is gesynchroniseerd met Supabase.");
  } catch (error) {
    console.warn("Handmatige cloud-sync mislukte:", error);
    window.alert("Cloud-sync is mislukt. Controleer of je SQL-setup en bucket in Supabase klaarstaan.");
  }
}

async function saveProfile(event) {
  event.preventDefault();
  state.profile.name = sanitizeText(profileNameInput.value, 80);
  state.profile.avatarUrl = sanitizeImageValue(profileAvatarUrlInput?.value || "");

  if (profileAvatarFileInput.files?.[0]) {
    const blob = await getCroppedAvatarBlob();
    state.profile.avatarUrl = await fileToDataUrl(blob || profileAvatarFileInput.files[0]);
  }

  persistAndRender();
  const user = await getCurrentSessionUser();
  if (user) {
    await saveProfileToCloud(user);
  }
  closeProfileModal();
}

async function saveProfileToCloud(user) {
  const client = getSupabaseClient();
  if (!client || !user) {
    return;
  }

  const payload = {
    id: user.id,
    email: user.email || "",
    display_name: state.profile?.name || "",
    avatar_url: state.profile?.avatarUrl || "",
  };

  const { error } = await client.from("profiles").upsert(payload, { onConflict: "id" });
  if (error) {
    console.warn("Profiel opslaan in Supabase mislukte:", error);
  }
}

async function buildCloudStateForUser(user) {
  const client = getSupabaseClient();
  if (!client || !user) {
    return createEmptyState();
  }

  const [profileResult, participantsResult, contributionsResult, expensesResult] = await Promise.all([
    client.from("profiles").select("display_name, avatar_url").eq("id", user.id).maybeSingle(),
    client.from("deelnemers").select("id, naam, kleur").eq("user_id", user.id).order("created_at", { ascending: true }),
    client.from("extra_inleg").select("id, participant_id, bedrag, type, omschrijving, datum").eq("user_id", user.id).order("datum", { ascending: false }),
    client.from("uitgaven").select("id, omschrijving, bedrag, categorie, betaald_door, datum, notitie, bon_path, is_gecontroleerd, is_raming").eq("user_id", user.id).order("datum", { ascending: false }),
  ]);

  if (participantsResult.error || contributionsResult.error || expensesResult.error) {
    throw new Error("Clouddata ophalen is mislukt.");
  }

  const participants = (participantsResult.data || []).map((item, index) => ({
    id: item.id,
    name: sanitizeText(item.naam) || `Deelnemer ${index + 1}`,
    color: item.kleur || fallbackColor(index),
  }));

  const contributions = (contributionsResult.data || []).map((item) => ({
    id: item.id,
    participantId: sanitizeText(item.participant_id || "", 80),
    amount: sanitizeAmount(item.bedrag),
    type: item.type === "initial" ? "initial" : "topup",
    note: sanitizeText(item.omschrijving),
    date: sanitizeDate(String(item.datum || "").slice(0, 10)),
  }));

  const expenseRows = expensesResult.data || [];
  const expenseRecords = [];
  const estimateRecords = [];

  for (const item of expenseRows) {
    const baseRecord = {
      id: item.id,
      description: sanitizeText(item.omschrijving) || (item.is_raming ? "Raming" : "Uitgave"),
      amount: sanitizeAmount(item.bedrag),
      category: categoryLabels[item.categorie] ? item.categorie : "overig",
      paidBy: sanitizeText(item.betaald_door),
      date: sanitizeDate(String(item.datum || "").slice(0, 10)),
      note: sanitizeText(item.notitie),
      receiptPath: sanitizeText(item.bon_path || "", 240),
      receiptImage: "",
      ocrStatus: item.is_gecontroleerd ? "reviewed" : "manual",
    };

    if (baseRecord.receiptPath) {
      baseRecord.receiptImage = await getSignedReceiptUrl(baseRecord.receiptPath);
    }

    if (item.is_raming) {
      estimateRecords.push(normalizeEstimate(baseRecord, participants.length));
    } else {
      expenseRecords.push(baseRecord);
    }
  }

  return normalizeState({
    weekend: state.weekend,
    auth: {
      loggedIn: true,
      provider: "supabase",
      email: user.email || "",
      userId: user.id,
      lastSyncedAt: new Date().toISOString(),
    },
    profile: {
      name: sanitizeText(profileResult.data?.display_name || state.profile?.name || "", 80),
      avatarUrl: sanitizeImageValue(profileResult.data?.avatar_url || state.profile?.avatarUrl || ""),
    },
    participants,
    contributions,
    expenses: expenseRecords,
    estimates: estimateRecords,
  });
}

function isCloudStateEmpty(cloudState) {
  return !hasMeaningfulState({
    participants: cloudState.participants,
    contributions: cloudState.contributions,
    expenses: cloudState.expenses,
    estimates: cloudState.estimates,
    profile: cloudState.profile,
  });
}

function applyCloudState(cloudState, user) {
  cloudHydrating = true;
  state = normalizeState({
    ...cloudState,
    auth: {
      loggedIn: true,
      provider: "supabase",
      email: user.email || "",
      userId: user.id,
      lastSyncedAt: new Date().toISOString(),
    },
  });
  writeToStorage(primaryStorageKey, JSON.stringify(state));
  writeToStorage(storageKey, JSON.stringify(state));
  render();
  cloudHydrating = false;
}

async function getSignedReceiptUrl(path) {
  const client = getSupabaseClient();
  if (!client || !path) {
    return "";
  }

  const { data, error } = await client.storage
    .from(getSupabaseConfig().mediaBucket)
    .createSignedUrl(path, 60 * 60);

  if (error) {
    console.warn("Signed URL voor bon ophalen mislukte:", error);
    return "";
  }

  return data?.signedUrl || "";
}

async function ensureReceiptUploaded(expense, userId) {
  const client = getSupabaseClient();
  if (!client || !expense) {
    return expense;
  }

  if (!expense.receiptImage && !expense.receiptPath) {
    return expense;
  }

  if (!/^data:image\//.test(expense.receiptImage || "")) {
    if (expense.receiptPath && !expense.receiptImage) {
      return {
        ...expense,
        receiptImage: await getSignedReceiptUrl(expense.receiptPath),
      };
    }
    return expense;
  }

  const blob = await fetch(expense.receiptImage).then((response) => response.blob());
  const extension = blob.type.includes("png") ? "png" : blob.type.includes("webp") ? "webp" : "jpg";
  const path = `receipts/${userId}/${expense.id}.${extension}`;

  const { error } = await client.storage
    .from(getSupabaseConfig().mediaBucket)
    .upload(path, blob, {
      upsert: true,
      contentType: blob.type || "image/jpeg",
    });

  if (error) {
    console.warn("Bon uploaden naar Supabase mislukte:", error);
    return expense;
  }

  return {
    ...expense,
    receiptPath: path,
    receiptImage: await getSignedReceiptUrl(path),
    ocrStatus: "reviewed",
  };
}

async function fetchExistingReceiptPaths(userId) {
  const client = getSupabaseClient();
  if (!client || !userId) {
    return [];
  }

  const { data, error } = await client
    .from("uitgaven")
    .select("bon_path")
    .eq("user_id", userId)
    .neq("bon_path", "");

  if (error) {
    console.warn("Bestaande bonpaden ophalen mislukte:", error);
    return [];
  }

  return (data || []).map((item) => sanitizeText(item.bon_path || "", 240)).filter(Boolean);
}

async function syncStateToCloud(reason = "auto") {
  const client = getSupabaseClient();
  const user = await getCurrentSessionUser();
  if (!client || !user || cloudHydrating) {
    return;
  }

  const normalized = normalizeState(state);
  const uploadedExpenses = [];
  for (const expense of normalized.expenses) {
    uploadedExpenses.push(await ensureReceiptUploaded(expense, user.id));
  }

  normalized.expenses = uploadedExpenses;
  state.expenses = uploadedExpenses;

  await saveProfileToCloud(user);

  const currentPaths = await fetchExistingReceiptPaths(user.id);
  const desiredPaths = new Set(uploadedExpenses.map((item) => item.receiptPath).filter(Boolean));
  const orphanPaths = currentPaths.filter((path) => !desiredPaths.has(path));

  const contributionsRows = normalized.contributions.map((item) => ({
    id: item.id,
    user_id: user.id,
    participant_id: item.type === "initial" ? item.participantId || null : null,
    omschrijving: item.note || "",
    bedrag: item.amount,
    type: item.type,
    is_raming: false,
    datum: `${item.date}T12:00:00.000Z`,
  }));

  const participantRows = normalized.participants.map((item) => ({
    id: item.id,
    user_id: user.id,
    naam: item.name,
    kleur: item.color,
  }));

  const expenseRows = normalized.expenses.map((item) => ({
    id: item.id,
    user_id: user.id,
    participant_id: null,
    omschrijving: item.description,
    bedrag: item.amount,
    categorie: item.category,
    betaald_door: item.paidBy || "",
    is_raming: false,
    is_gecontroleerd: item.ocrStatus === "reviewed",
    datum: `${item.date}T12:00:00.000Z`,
    notitie: item.note || "",
    bon_path: item.receiptPath || "",
  }));

  const estimateRows = normalized.estimates.map((item) => ({
    id: item.id,
    user_id: user.id,
    participant_id: null,
    omschrijving: item.description,
    bedrag: item.amount,
    categorie: item.category,
    betaald_door: item.paidBy || "",
    is_raming: true,
    is_gecontroleerd: false,
    datum: `${item.date}T12:00:00.000Z`,
    notitie: item.note || "",
    bon_path: "",
  }));

  const { error: deleteContributionsError } = await client.from("extra_inleg").delete().eq("user_id", user.id);
  if (deleteContributionsError) {
    throw deleteContributionsError;
  }

  const { error: deleteExpensesError } = await client.from("uitgaven").delete().eq("user_id", user.id);
  if (deleteExpensesError) {
    throw deleteExpensesError;
  }

  const { error: deleteParticipantsError } = await client.from("deelnemers").delete().eq("user_id", user.id);
  if (deleteParticipantsError) {
    throw deleteParticipantsError;
  }

  if (participantRows.length) {
    const { error } = await client.from("deelnemers").insert(participantRows);
    if (error) throw error;
  }

  if (contributionsRows.length) {
    const { error } = await client.from("extra_inleg").insert(contributionsRows);
    if (error) throw error;
  }

  if (expenseRows.length || estimateRows.length) {
    const { error } = await client.from("uitgaven").insert([...expenseRows, ...estimateRows]);
    if (error) throw error;
  }

  if (orphanPaths.length) {
    await client.storage.from(getSupabaseConfig().mediaBucket).remove(orphanPaths);
  }

  state.auth.loggedIn = true;
  state.auth.provider = "supabase";
  state.auth.email = user.email || "";
  state.auth.userId = user.id;
  state.auth.lastSyncedAt = new Date().toISOString();
  writeToStorage(primaryStorageKey, JSON.stringify(state));
  writeToStorage(storageKey, JSON.stringify(state));
  render();
  if (reason === "manual") {
    console.info("Cloud-sync voltooid.");
  }
}

function queueCloudSync(reason = "auto") {
  if (!state.auth?.loggedIn || cloudHydrating || !isSupabaseConfigured()) {
    return;
  }

  if (cloudSyncPromise) {
    cloudSyncQueued = true;
    return;
  }

  cloudSyncPromise = syncStateToCloud(reason)
    .catch((error) => {
      console.warn("Cloud-sync mislukte:", error);
    })
    .finally(() => {
      cloudSyncPromise = null;
      if (cloudSyncQueued) {
        cloudSyncQueued = false;
        queueCloudSync("queued");
      }
    });
}

async function hydrateFromSupabaseSession(user) {
  const cloudState = await buildCloudStateForUser(user);
  if (isCloudStateEmpty(cloudState) && hasMeaningfulState(state) && !wasMigrationDone(user.id)) {
    await syncStateToCloud("initial-migration");
    markMigrationDone(user.id);
    applyCloudState(await buildCloudStateForUser(user), user);
    return;
  }

  applyCloudState(cloudState, user);
}

async function bootstrapCloudFeatures() {
  bindAuthModal();
  renderAccountUi();

  const client = getSupabaseClient();
  if (!client) {
    return;
  }

  if (!authStateListenerBound) {
    authStateListenerBound = true;
    client.auth.onAuthStateChange(async (event, session) => {
      if (event === "SIGNED_OUT" || !session?.user) {
        if (state.auth?.loggedIn) {
          state = createEmptyState();
          writeToStorage(primaryStorageKey, JSON.stringify(state));
          writeToStorage(storageKey, JSON.stringify(state));
          render();
        }
        return;
      }
      if (event === "SIGNED_IN" || event === "TOKEN_REFRESHED" || event === "INITIAL_SESSION") {
        await hydrateFromSupabaseSession(session.user);
      }
    });
  }

  const user = await getCurrentSessionUser();
  if (user) {
    await hydrateFromSupabaseSession(user);
  }
}

async function exportStateToFile() {
  const payload = {
    version: 2,
    exportedAt: new Date().toISOString(),
    app: "Pot z,n Loatst",
    data: state,
  };
  const fileName = `potzloats-${todayIso()}.json`;
  const json = JSON.stringify(payload, null, 2);
  const blob = new Blob([json], { type: "application/json" });

  if (typeof File === "function" && navigator.share && navigator.canShare) {
    try {
      const shareFile = new File([blob], fileName, { type: "application/json" });
      if (navigator.canShare({ files: [shareFile] })) {
        await navigator.share({
          files: [shareFile],
          title: "Pot z,n Loatst export",
          text: "Bewaar of deel je potbestand.",
        });
        return;
      }
    } catch (error) {
      console.warn("Delen van exportbestand mislukt, probeer downloadfallback.", error);
    }
  }

  const url = URL.createObjectURL(blob);
  const link = document.createElement("a");
  link.href = url;
  link.download = fileName;
  link.rel = "noopener";
  document.body.append(link);
  link.click();
  link.remove();

  window.setTimeout(() => URL.revokeObjectURL(url), 1000);

  if (/iPad|iPhone|iPod/.test(navigator.userAgent) && !navigator.share) {
    window.open(url, "_blank", "noopener");
  }
}

async function importStateFromFile(event) {
  const file = event.target.files?.[0];
  if (!file) {
    return;
  }

  try {
    const text = await readFileAsText(file);
    const parsed = JSON.parse(text);
    const nextValue = parsed && typeof parsed === "object" ? parsed.data || parsed : null;
    if (!nextValue || typeof nextValue !== "object" || Array.isArray(nextValue)) {
      throw new Error("Ongeldig bestand");
    }
    state = normalizeState(nextValue);
    resetUiState();
    persistAndRender();
  } catch (error) {
    window.alert("Kon dit bestand niet inlezen als Pot z,n Loatst-data.");
  } finally {
    if (importStateFileInput) importStateFileInput.value = "";
  }
}

function removeRecord(kind, id) {
  if (kind === "contribution" || kind === "topup") {
    state.contributions = state.contributions.filter((item) => item.id !== id);
  } else if (kind === "estimate") {
    state.estimates = state.estimates.filter((item) => item.id !== id);
  } else {
    state.expenses = state.expenses.filter((item) => item.id !== id);
  }

  if (editingRecord?.id === id && editingRecord?.kind === kind) {
    editingRecord = null;
  }
}

async function requestReceiptAnalysis(payload) {
  const file = expenseReceiptInput.files?.[0] || null;
  const requestPayload = {
    ...payload,
    file,
    fileName: payload?.fileName || file?.name || "",
    notesHint: payload?.notesHint || [expenseDescriptionInput.value, expenseNoteInput.value].filter(Boolean).join(" "),
  };

  if (file && globalThis.Tesseract) {
    try {
      setReceiptProgress("Bon scannen...");
      const ocrText = await recognizeReceiptText(file);
      lastReceiptOcrText = ocrText;
      return buildReceiptSuggestionFromText(ocrText, requestPayload, "ocr");
    } catch (error) {
      console.warn("OCR met Tesseract mislukte, lokale fallback wordt gebruikt.", error);
    }
  }

  return analyzeReceiptLocally(requestPayload, false);
}

async function recognizeReceiptText(file) {
  const result = await globalThis.Tesseract.recognize(file, "eng", {
    logger: (message) => {
      if (message?.status) {
        const progress = typeof message.progress === "number" ? ` (${Math.round(message.progress * 100)}%)` : "";
        setReceiptProgress(`${capitalize(message.status)}${progress}`);
      }
    },
  });

  return String(result?.data?.text || "");
}

function setReceiptProgress(message) {
  if (ocrStatus) {
    ocrStatus.textContent = message;
  }
}

function buildReceiptSuggestionFromText(text, payload, source = "ocr") {
  const normalizedText = String(text || "").replace(/\u00a0/g, " ").trim();
  const amount = parseAmountFromText(normalizedText);
  const firstLine = normalizedText
    .split(/\r?\n/)
    .map((line) => sanitizeText(line, 80))
    .find((line) => line && !/\d{2}[:.]\d{2}/.test(line));

  return {
    amount,
    date: parseDateFromText(normalizedText) || todayIso(),
    description: firstLine || prettifyReceiptName(payload.fileName || ""),
    category: inferCategory(`${normalizedText} ${payload.notesHint || ""}`),
    confidence: amount ? 0.78 : 0.28,
    ocrStatus: amount ? "suggested" : "manual_required",
    message: amount
      ? source === "ocr"
        ? "OCR heeft een suggestie gemaakt. Controleer vooral het bedrag bij 'te betalen' of 'totaal'."
        : "Lokale suggestie gemaakt. Controleer vooral het bedrag bij 'te betalen' of 'totaal'."
      : "Ik kon geen betrouwbaar bedrag lezen. Tik op het bonvoorbeeld om te vergroten en vul het bedrag handmatig in.",
  };
}

function analyzeReceiptLocally(payload, serverFailed) {
  const combined = [payload.fileName || "", payload.notesHint || "", lastReceiptOcrText || ""].filter(Boolean).join(" ");
  const amount = parseAmountFromText(combined);

  return {
    amount,
    date: parseDateFromText(combined) || todayIso(),
    description: prettifyReceiptName(payload.fileName || ""),
    category: inferCategory(combined),
    confidence: amount ? 0.44 : 0.16,
    ocrStatus: amount ? "suggested" : "manual_required",
    message: amount
      ? serverFailed
        ? "Serveranalyse was niet beschikbaar, dus ik heb lokaal een voorzichtige suggestie gemaakt. Controleer vooral het bedrag bij 'te betalen'."
        : "Lokale suggestie gemaakt. Controleer vooral het bedrag bij 'te betalen' of 'totaal'."
      : "Ik kon geen betrouwbaar bedrag herkennen. Tik op het bonvoorbeeld om het te vergroten en vul het juiste bedrag handmatig in.",
  };
}

function parseAmountFromText(text) {
  const prioritized = extractKeywordAmount(text);
  if (prioritized !== null) {
    return prioritized;
  }

  const normalized = String(text || "")
    .toLowerCase()
    .replace(/(\d)[,](\d{2})\b/g, "$1.$2")
    .replace(/[^0-9.\n ]/g, " ");
  const matches = normalized.match(/\d+(?:\.\d{1,2})?/g) || [];
  const values = matches
    .map((value) => Number(value))
    .filter((value) => Number.isFinite(value) && value > 0 && value < 10000);

  if (!values.length) {
    return null;
  }

  const decimalValues = matches
    .filter((value) => /\.\d{1,2}$/.test(value))
    .map((value) => Number(value))
    .filter((value) => Number.isFinite(value) && value > 0 && value < 10000);

  if (decimalValues.length) {
    return decimalValues.sort((a, b) => b - a)[0];
  }

  return values.sort((a, b) => b - a)[0];
}

function extractKeywordAmount(text) {
  const normalized = String(text || "")
    .toLowerCase()
    .replace(/(\d)[,](\d{2})\b/g, "$1.$2")
    .replace(/\s+/g, " ");

  const patterns = [
    /te betalen[^0-9]{0,16}(\d+(?:\.\d{1,2})?)/,
    /totaal(?:bedrag)?[^0-9]{0,16}(\d+(?:\.\d{1,2})?)/,
    /total(?: amount)?[^0-9]{0,16}(\d+(?:\.\d{1,2})?)/,
    /amount due[^0-9]{0,16}(\d+(?:\.\d{1,2})?)/,
    /te voldoen[^0-9]{0,16}(\d+(?:\.\d{1,2})?)/,
    /saldo[^0-9]{0,16}(\d+(?:\.\d{1,2})?)/,
    /sum[^0-9]{0,16}(\d+(?:\.\d{1,2})?)/,
    /netto[^0-9]{0,16}(\d+(?:\.\d{1,2})?)/,
    /(\d+(?:\.\d{1,2})?)[^a-z0-9]{0,12}(?:eur|euro|€)/,
  ];

  for (const pattern of patterns) {
    const match = normalized.match(pattern);
    if (match) {
      const amount = Number(match[1]);
      if (Number.isFinite(amount) && amount > 0 && amount < 10000) {
        return amount;
      }
    }
  }

  return null;
}

function registerServiceWorker() {
  if (!("serviceWorker" in navigator) || location.protocol === "file:") {
    return;
  }

  window.addEventListener("load", async () => {
    try {
      await navigator.serviceWorker.register("./sw.js");
    } catch (error) {
      console.warn("Service worker registreren mislukt:", error);
    }
  });
}

function capitalize(value) {
  const text = String(value || "");
  return text ? text.charAt(0).toUpperCase() + text.slice(1) : "";
}

function resetExpenseComposer() {
  expenseForm.reset();
  expenseKindInput.value = "expense";
  estimatePricingModeInput.value = "total";
  expenseDateInput.value = todayIso();
  pendingReceiptImage = "";
  lastReceiptOcrText = "";
  receiptReview.hidden = true;
  renderExpenseComposerState();
}

expenseReceiptInput?.addEventListener("change", () => {
  lastReceiptOcrText = "";
});

bootstrapCloudFeatures();

function getEstimateAmount(record) {
  if (record?.pricingMode === "per_person") {
    const participantCount = Math.max(1, Number(record.participantCountSnapshot) || 1);
    const perPersonAmount = sanitizeAmount(record.perPersonAmount || 0);
    return sanitizeAmount(perPersonAmount * participantCount);
  }
  return sanitizeAmount(record?.amount || 0);
}

function renderEstimateSummaryText(record) {
  const participantCount = Math.max(1, Number(record.participantCountSnapshot) || 1);
  const perPersonAmount = sanitizeAmount(record.perPersonAmount || 0);
  return `${currencyFormatter.format(perPersonAmount)} p.p. x ${participantCount} deelnemers = ${currencyFormatter.format(getEstimateAmount(record))}`;
}

function renderExpenseComposerState() {
  const isEstimate = expenseKindInput.value === "estimate";
  const perPersonMode = isEstimate && estimatePricingModeInput.value === "per_person";

  // Show the pricing-mode section for any estimate, hide for regular expenses
  estimatePerPersonWrap.hidden = !isEstimate;

  // Within the section: hide per-person amount row when in total mode
  const perPersonAmountLabel = estimatePerPersonAmountInput?.closest("label");
  if (perPersonAmountLabel) perPersonAmountLabel.hidden = !perPersonMode;
  if (estimateCalculation) estimateCalculation.hidden = !perPersonMode;

  expenseForm.querySelector('button[type="submit"]').textContent = isEstimate ? "Raming opslaan" : "Uitgave opslaan";
  expenseReceiptInput.closest("label").hidden = isEstimate;
  analyzeReceiptButton.hidden = isEstimate;
  if (isEstimate) receiptReview.hidden = true;

  if (perPersonMode) {
    const participantCount = Math.max(0, state.participants.length);
    const perPersonAmount = sanitizeAmount(estimatePerPersonAmountInput?.value);
    expenseAmountInput.placeholder = "Wordt automatisch berekend";
    expenseAmountInput.readOnly = true;
    expenseAmountInput.value = participantCount ? String(sanitizeAmount(perPersonAmount * participantCount)) : "";
    if (estimateCalculation) {
      estimateCalculation.textContent = participantCount
        ? `${currencyFormatter.format(perPersonAmount)} p.p. × ${participantCount} deelnemers = ${currencyFormatter.format(perPersonAmount * participantCount)}`
        : "Voeg eerst deelnemers toe om per persoon te berekenen.";
    }
  } else {
    expenseAmountInput.readOnly = false;
    expenseAmountInput.placeholder = "125";
  }
}

function updateEstimateEditMode(container) {
  if (!container) {
    return;
  }
  const pricingModeField = container.querySelector('[data-field="pricingMode"]');
  if (!pricingModeField) {
    return;
  }
  const isPerPerson = pricingModeField.value === "per_person";
  container.querySelectorAll("[data-per-person-group], [data-per-person-summary]").forEach((element) => {
    element.hidden = !isPerPerson;
  });
  if (!isPerPerson) {
    return;
  }
  const perPersonAmount = sanitizeAmount(container.querySelector('[data-field="perPersonAmount"]')?.value);
  const participantCountSnapshot = Math.max(1, Number(container.querySelector('[data-field="participantCountSnapshot"]')?.value) || state.participants.length || 1);
  const summary = container.querySelector("[data-per-person-summary]");
  if (summary) {
    summary.textContent = renderEstimateSummaryText({
      pricingMode: "per_person",
      perPersonAmount,
      participantCountSnapshot,
      amount: sanitizeAmount(perPersonAmount * participantCountSnapshot),
    });
  }
}





